(2852, 333, '_wp_attachment_metadata', 'a:5:{s:5:\"width\";i:768;s:6:\"height\";i:427;s:4:\"file\";s:65:\"2021/07/to-5-nganh-nghe-hot-nhat-nam-2018-telesales-768x427-1.jpg\";s:5:\"sizes\";a:2:{s:6:\"medium\";a:4:{s:4:\"file\";s:65:\"to-5-nganh-nghe-hot-nhat-nam-2018-telesales-768x427-1-300x167.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:167;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:9:\"thumbnail\";a:4:{s:4:\"file\";s:64:\"to-5-nganh-nghe-hot-nhat-nam-2018-telesales-768x427-1-150x83.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:83;s:9:\"mime-type\";s:10:\"image/jpeg\";}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),
(2853, 297, '_industry_challenge', '<p>著中國大陸及東南亞國家的興起，台灣手工具漸漸走出「量產」的思維，擺脫以前的以訂單數量來取得成長的舊思維，並且邁向「少量精產」的特殊高值化的手工具產品。 <br />手工具業管理挑戰有以下：</p>\r\n<ul>\r\n<li>\r\n<p>有效率的的產品開發與圖文管理</p>\r\n</li>\r\n<li>\r\n<p>完整的產品型號與品號管理</p>\r\n</li>\r\n<li>\r\n<p>快速取得多來源成本分析，進行估報價管理</p>\r\n</li>\r\n<li>\r\n<p>彈性的加工、包裝方式管理</p>\r\n</li>\r\n<li>\r\n<p>關鍵原料採購管理</p>\r\n</li>\r\n<li>\r\n<p>即時掌控生產進度時程</p>\r\n</li>\r\n<li>\r\n<p>外包廠商製程資訊回饋管理</p>\r\n</li>\r\n<li>\r\n<p>製程損耗管理</p>\r\n</li>\r\n<li>\r\n<p>庫存&amp;批號追蹤管理</p>\r\n</li>\r\n</ul>');
INSERT INTO `dgw_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(2854, 297, '_industry_solution', '<h3 align=\"center\"><span class=\"txt15\">手工具行業解決方案架構圖<br /></span><img src=\"http://www.digiwin.com.vn/tw/industry/G/images/G2-1.jpg\" width=\"620\" height=\"447\" /></h3>\r\n<h3 align=\"center\"><span class=\"txt15\"><br />建構企業營運資訊整合力關鍵 手工具產業e化解決方案</span><img src=\"http://www.digiwin.com.vn/tw/industry/G/images/G2-2.jpg\" width=\"598\" height=\"371\" /></h3>\r\n<p>　　在手工具產業e化解決方案中，在外部面對客戶經營，我們提供營銷管理平台；面對採購及加工廠商，有協力廠管理平台。在內部面對管理及生產，有產銷協調、合約採購、資材、生產追蹤、成本分析等管理平台。</p>\r\n<h3 align=\"center\">營銷管理功能特色</h3>\r\n<table border=\"0\" width=\"550\" cellspacing=\"1\" cellpadding=\"3\" align=\"center\" bgcolor=\"#b1b1b1\">\r\n<tbody>\r\n<tr>\r\n<td class=\"h_legendB\" align=\"center\" bgcolor=\"#E7EDF5\">估報價管理</td>\r\n<td class=\"h_legendB\" align=\"center\" bgcolor=\"#E7EDF5\">接單管理</td>\r\n</tr>\r\n<tr>\r\n<td bgcolor=\"#F7FAFD\">可挑選包裝、加工方式進行單件、工具箱組進行成本估價</td>\r\n<td bgcolor=\"#F7FAFD\">對變更交期提供「快速變更預交日」快速變更</td>\r\n</tr>\r\n<tr>\r\n<td bgcolor=\"#F7FAFD\">報價及接單均有「最低受訂量」的建議</td>\r\n<td bgcolor=\"#F7FAFD\">提供記錄完善的接單資訊轉生產進度與出貨的跟催管理</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p align=\"center\"> </p>\r\n<h3 align=\"center\">產銷協調管理功能特色</h3>\r\n<table border=\"0\" width=\"550\" cellspacing=\"1\" cellpadding=\"3\" align=\"center\" bgcolor=\"#b1b1b1\">\r\n<tbody>\r\n<tr>\r\n<td class=\"h_legendB\" align=\"center\" bgcolor=\"#E7EDF5\" width=\"183\">產銷協調</td>\r\n<td class=\"h_legendB\" align=\"center\" bgcolor=\"#E7EDF5\" width=\"183\">包裝排程</td>\r\n<td class=\"h_legendB\" align=\"center\" bgcolor=\"#E7EDF5\" width=\"183\">訂單交期</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#F7FAFD\" width=\"183\">提供訂單變更影響相關採購及製令之變更建議，且自動產出「採購變更單、製令變更單」，以利掌握生產排程</td>\r\n<td valign=\"top\" bgcolor=\"#F7FAFD\" width=\"183\">可依業務安排之出貨排程提供給最終組裝包裝人員進行包裝排程參考</td>\r\n<td valign=\"top\" bgcolor=\"#F7FAFD\" width=\"183\">可針對未出貨之訂單進行交期調整管理，並提供給生管單位進行相關對應之排程修正</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p align=\"center\"> </p>\r\n<h3 align=\"center\">協力廠商管理功能特色</h3>\r\n<table border=\"0\" width=\"550\" cellspacing=\"1\" cellpadding=\"3\" align=\"center\" bgcolor=\"#b1b1b1\">\r\n<tbody>\r\n<tr>\r\n<td class=\"h_legendB\" align=\"center\" bgcolor=\"#E7EDF5\" width=\"183\">用料管理</td>\r\n<td class=\"h_legendB\" align=\"center\" bgcolor=\"#E7EDF5\" width=\"183\">加工管理</td>\r\n<td class=\"h_legendB\" align=\"center\" bgcolor=\"#E7EDF5\" width=\"183\">連續委外</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#F7FAFD\" width=\"183\">掌握各外包倉之料件呆滯、週轉率，以協助訂定物料參考</td>\r\n<td valign=\"top\" bgcolor=\"#F7FAFD\" width=\"183\">自動產生委外加工LOSS率及扣款計算，以節省結帳時間</td>\r\n<td rowspan=\"2\" valign=\"top\" bgcolor=\"#F7FAFD\" width=\"183\">委外加工站多，每站都管其開工日、完工日、數量(單重、重量、換算)、製程，並利用看板管理來執行管控</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#F7FAFD\" width=\"183\">協力廠多點倉庫間之轉撥或調撥處理</td>\r\n<td valign=\"top\" bgcolor=\"#F7FAFD\" width=\"183\">看板以燈號顯示製令狀態，使加工單位依序進行減少協調時間</td>\r\n</tr>\r\n</tbody>\r\n</table>'),
(2855, 297, '_thumbnail_id', '333'),
(2856, 296, '_industry_challenge', '<h3>各職能所面臨之管理挑戰：</h3>\r\n<p align=\"center\"><img src=\"http://www.digiwin.com.vn/tw/industry/I/images/pic-i4.jpg\" width=\"590\" height=\"579\" /></p>\r\n<h3>SWOT分析：</h3>\r\n<p align=\"center\"><img src=\"http://www.digiwin.com.vn/tw/industry/I/images/pic-i5.jpg\" width=\"577\" height=\"346\" /></p>\r\n<p>&nbsp;</p>'),
(2857, 296, '_industry_solution', '<h3>紡織業在生產規劃所面臨的挑戰</h3>\r\n<p align=\"center\"><img src=\"http://www.digiwin.com.vn/tw/industry/I/images/pic-i3.jpg\" width=\"500\" height=\"332\" /></p>\r\n<h3>紡織業資訊化解決方案</h3>\r\n<p>隨著營運成本節節高漲，紡織業要如何維持以往的營收達成率呢？<br />在此提供幾個紡織業資訊化解決方案：</p>\r\n<p align=\"center\"><img src=\"http://www.digiwin.com.vn/tw/industry/I/images/pic-i6.jpg\" width=\"700\" height=\"339\" /></p>\r\n<p>另外，由於紡織業是個相當特殊的產業，生產範圍涵蓋原料端、纖維、紡紗、纖布到終製品端成衣等上、中、下游建構完整供應鏈，因此非常重視生產規劃過程的排成嚴謹性，此針對紡織業生產規劃流程，再進行深度的資訊解決方案說明：</p>\r\n<p align=\"center\"><img src=\"http://www.digiwin.com.vn/tw/industry/I/images/pic-i7.jpg\" width=\"700\" height=\"440\" /></p>\r\n<p>&nbsp;</p>'),
(2858, 336, '_wp_attached_file', '2021/06/b1-02.jpg'),
(2859, 336, '_wp_attachment_metadata', 'a:5:{s:5:\"width\";i:580;s:6:\"height\";i:422;s:4:\"file\";s:17:\"2021/06/b1-02.jpg\";s:5:\"sizes\";a:2:{s:6:\"medium\";a:4:{s:4:\"file\";s:17:\"b1-02-300x218.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:218;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:9:\"thumbnail\";a:4:{s:4:\"file\";s:17:\"b1-02-150x109.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:109;s:9:\"mime-type\";s:10:\"image/jpeg\";}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),
(2860, 135, '_industry_challenge', '<p>台灣塑膠製品業者工廠家數多，產品種類眾多，採少量多樣化生產，大多以中小企業為主，以機動靈活、交貨迅速、交期彈性大為競爭優勢，整個塑膠製品業之上、中、下游及週邊產業體系完整、且產業關聯性高，支援重要產業如光電、醫療及環保等，外銷依存度高，但產業勞力密集度高，資本密集度低。</p>\r\n<p>　　OEM塑膠製品廠，通常提供模具設計、模具生產、模具代管理、產品射出及後加工處理服務，很少有標準品，大部分採接單生產，著重於訂單專案管理；訂單絕大部分來自舊客，或原舊客介紹之新客，少有自行開發新客戶之業務活動行為；OBM塑膠製品廠(如塑膠文具、塑膠玩具、塑膠家用品)，大部分為自有產品，採計畫生產居多，公司營收需倚賴業務開發與參展、廣告。</p>\r\n<p>　　塑膠製品業之訂單交貨期均很短(不包括模具設計、生產及試模、試產)，但該產業生產換線時間較長，生產排程是管理重點，會協助客戶進行模具設計、生產(也需進行模具壽命管理)，後加工製程多，生產過程較不易管控。</p>'),
(2861, 135, '_industry_solution', '<p><img class=\"aligncenter wp-image-336 size-full\" src=\"http://digiwin.astcc24.net/wp-content/uploads/2021/06/b1-02.jpg\" alt=\"\" width=\"580\" height=\"422\" /></p>'),
(2862, 206, '_industry_challenge', '<table border=\"0\" width=\"620\" cellspacing=\"1\" cellpadding=\"5\" align=\"center\" bgcolor=\"#b1b1b1\">\r\n<tbody>\r\n<tr>\r\n<td bgcolor=\"#CCCCCC\" width=\"47\">\r\n<p align=\"center\"> </p>\r\n</td>\r\n<td align=\"center\" valign=\"middle\" bgcolor=\"#CCCCCC\">行業挑戰</td>\r\n<td align=\"center\" valign=\"middle\" bgcolor=\"#CCCCCC\">管理重點</td>\r\n</tr>\r\n<tr>\r\n<td rowspan=\"9\" align=\"center\" bgcolor=\"#FFFFFF\">\r\n<h2>生<br />產<br />面</h2>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"215\">\r\n<h3>工裝夾、量、刀具的管理死角</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"354\">生產過程中需要有機器設備、工裝夾、量、刀具等訊息，所需領用刀工具異動頻繁，有時還會有借出、借入狀況發生，對於此類工具管理不易。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"215\">\r\n<h3>模具設計、製造及攤模難以管理</h3>\r\n</td>\r\n<td valign=\"middle\" bgcolor=\"#FAF7F3\" width=\"354\">模具壽命、產能數量、修模管理以及模具費用分攤。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"215\">\r\n<h3>下腳料(次級料)的的管控</h3>\r\n</td>\r\n<td valign=\"middle\" bgcolor=\"#FFFFFF\" width=\"354\">次級料需能管理，在生產時可知當次的可添加多少的回收料。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"215\">\r\n<h3>成品及半成品並存行生產計畫</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"354\">生產過程所需機器設備和工模具種類繁多，零組件製造週期長短不一，加工製程複雜和途程的不確定性造成在製品管理不易，且經常有不易控管的邊料產生。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"215\">\r\n<h3>加工程序繁複</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"354\">訂單的不確定性，零組件及產品的生產需要一定的週期，不當的料件的供應將產生的庫存積壓或停工待料的情況，難以精確的制訂出適時適量的生產、採購計劃。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"215\">\r\n<h3>在製品管理不易</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"354\">一般採用自製與委外加工相結合的方式，須對眾多委外商進行生產及加工進度和數量品質的追蹤管理。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">\r\n<h3>一物多品號，重複編碼</h3>\r\n</td>\r\n<td valign=\"middle\" bgcolor=\"#FFFFFF\">料件編碼未能檢查，造成重複編碼。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">\r\n<h3>ISO及TS16949的相關管制圖費工</h3>\r\n</td>\r\n<td valign=\"middle\" bgcolor=\"#FFFFFF\">使用EXCEL做品質管圖，不易管理，費工費時。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"215\">\r\n<h3>協力廠商配合</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"354\">提供平台，讓協力廠商上網抓取相關交易資料。</td>\r\n</tr>\r\n<tr>\r\n<td rowspan=\"2\" bgcolor=\"#FFFFFF\">\r\n<h2 align=\"center\">成<br />本<br />面</h2>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"215\">\r\n<h3>成本計算繁複</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"354\">原物料零組件品項多且複雜，材料價格變動大，導致成本精算不易，報價無法快速準確的反應市場。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"215\">\r\n<h3>原料價格波動快速</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"354\">因原材料的價格一直在波動，面對占成本結構中80%的原材料，且因材質、形狀等特性，經常會有供應商多送貨的情況，如何處理原材料實際操作中很難控制。</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>'),
(2863, 206, '_industry_solution', '<h4>(1)特色</h4>\r\n<table border=\"0\" width=\"620\" cellspacing=\"1\" cellpadding=\"5\" align=\"center\" bgcolor=\"#b1b1b1\">\r\n<tbody>\r\n<tr>\r\n<td align=\"center\" valign=\"top\" bgcolor=\"#CCCCCC\" width=\"146\">特色</td>\r\n<td align=\"center\" valign=\"top\" bgcolor=\"#CCCCCC\" width=\"451\">解決方案</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"146\">\r\n<h3>行銷參展</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">名片與問卷收集協助業務縮短銷售時程，搶先對手取得商機拉大競爭差距 ，多維度效益分析有效洞悉行銷活動。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"146\">\r\n<h3>模具及攤模管理</h3>\r\n</td>\r\n<td valign=\"middle\" bgcolor=\"#FAF7F3\">模具壽命管理、何時需修模及客戶及廠商的模具費用分攤。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"146\">\r\n<h3>自動編碼引導</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">彈性易於使用的編碼原則功能，可自行定義料件相關欄位，編碼人員快速辨識此料編已編否，如未編則自動生成編碼，使用者可依尋產品，解決編碼複雜問題。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"146\">\r\n<h3>建立CAD與ERP高度整合介面</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\">系統間可交換資料，減少重複輸入，壓縮產品開發時程，品號建檔可同步編修圖檔並列印。CAD列印圖表亦可取得ERP之BOM及製程資料，方便研發人員取用。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"146\">\r\n<h3>製程追蹤及排程</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">可依據機台產能及模／工具產能結合料況直接推算生產排程；Web化多職能平台，輕鬆掌握廠內外資訊。提供生產設備/派工執行等各類電子看板。自訂品質需收集之資料，幫助產品追溯。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"146\">\r\n<h3>強大的實際成本自動計算功能</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\">每張製令的生產成本和每一階半成品和最終成品的單元成本，人工和費用的分攤提供靈活的選擇，確實提供實際成本為報價的依歸，並檢討實際成本和標準成本的差異，力求改善降低成本增加獲利。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"146\">\r\n<h3>產品溯源</h3>\r\n</td>\r\n<td valign=\"middle\" bgcolor=\"#FFFFFF\">快速回溯有瑕疵的半成品或成品，快速回應客戶已發現的問題。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"146\" height=\"120\">\r\n<h3>品質管理</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\">評估監控計量值的整體製程能力；管制圖的異常圖點上，可註記和顯示異常原因及矯正措施，統計出哪些計數值不良項目發生的頻率最高，然後針對這些關鍵少數的不良項目進行個個擊破，以達到事半功倍、大幅降低整體不良的改善功效。</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"146\">\r\n<h3>導入批次生產計畫</h3>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">將整個原物料採購及半成品生產，包括委外件，納入整個排產計劃，快速產生製令單及採購單節省人力，並增進計劃之效率及正確性，減少待料，降低庫存成本。</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"C1\">\r\n<h4>(2)加值應用</h4>\r\n<h3>CRM客戶關係管理系統</h3>\r\n<p>從參展行銷取得客戶的相關資料，進而進入報價打樣送樣階段，最終至接到客戶的正式訂單的相關流程管理模式。而在這一階段也考驗大多數企業的資訊統整的能力及資訊傳遞的效率！</p>\r\n<h3>同步整合PDM</h3>\r\n<p>縮短新產品研發時間，運用協同設計與客戶共同研發產品，減少修正率，快速反應市場需求，研發設計到生產出貨一條鞭，減少管理成本及損失，奪得市場先機。</p>\r\n<h3>APS生產排程系統</h3>\r\n<p>減少規劃時間，降低人力負擔，當公司營運規模擴充時，有效進行物料/產能規劃作業，提升應變與處理異常狀況之能力與速度；降低庫存水準，提高庫存週轉率，達到及時性(JIT)生產，快速回覆客戶詢單交期，提升訂單達交率，產銷協調的依據。</p>\r\n<h3>e-B Online商務在線 商機無限</h3>\r\n<p>買方：</p>\r\n<p>1.帶動供應鏈體系之廠商在資訊傳遞上更為快速，提高生產力。</p>\r\n<p>2.縮短供應鏈週期，提昇整體競爭力。</p>\r\n<p>3.提昇交期的準確性</p>\r\n<p>4.加速客戶訂單的回應時間</p>\r\n<p>賣方：  </p>\r\n<p>1.提昇回應客戶訂單時效</p>\r\n<p>2.強化電子化的作業能力</p>\r\n<p>3.與客戶資訊緊密連結，提昇客戶忠誠度</p>\r\n<h3><a href=\"http://www.digiwin.com.vn/tw/solution_SFT1.html\">SFT廠區追蹤</a></h3>\r\n<p>SFT可以簡單定義為企業的「即時生產資訊追蹤系統」，提供企業自接單、投料、製造、外包、至完工入庫，全程掌握生產資訊，藉以緊密串接現場製程與ERP作業，落實企業管理循環。</p>\r\n<h3>TRC產品溯源</h3>\r\n<p>1.快速回溯有(可能有)瑕疵的半成品或成品</p>\r\n<p>2.快速回應客戶已發現的問題及時避免未來可能發生的問題</p>\r\n<p>3.建立客戶使用信心與品牌競爭力</p>\r\n<p>4.預防問題發生與減少賠償風險</p>\r\n<p>5.「有能力回溯」將是廠商接單基本條件</p>\r\n<h3>SPC品質管制</h3>\r\n<p>在現今企業競爭日益激烈情況下，SPC（Statistical Process Control；統計製程管制）為維持企業生產力和競爭力的一項利器，同時更為品管七大手法中的一重要方法。傳統以加強檢驗來保證品質的方式，往往僅能對產品進行消極性的修護、報廢等方式處理，而無法真正達到預防製程不良的目標。而SPC統計製程管制的目的，在於將生產線的品質狀況以統計分析的手法，能夠及時發現並排除造成製程不穩定的因子，達到穩定製程和產品品質、降低不良率的目的。</p>\r\n</div>\r\n<p>&nbsp;</p>'),
