INSERT INTO `dgw_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(2941, 111, '_solution_features', '<p>Tố chức tập đoàn</p>\r\n<p>TIPTOP GP hỗ trợ cơ cấu tập đoàn đa tổ chức, quản lý hỗn hợp, quản lý rời rạc, quản lý tập trung của tập đoàn đa cấp</p>\r\n<p>Hệ thống pháp luật và hệ thống quản lý tổ chức theo nhu cầu thực tế của doanh nghiệp, thiết lập linh hoạt cấu trúc đa tổ chức.</p>\r\n<p>&nbsp;</p>\r\n<hr class=\"hr\" />\r\n<p><a class=\"examplelink\" title=\"Dự toán cho tập đoàn\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop2_vn.jpg\" alt=\"Dự toán cho tập đoàn\" width=\"220\" height=\"198\" align=\"right\" /></a>Dự toán cho tập đoàn</p>\r\n<p>Kế hoạch và dự toán chính xác là mục tiêu cơ bản cần đạt được của kinh doanh, kết hợp với lịch sử bán hàng, yếu tố thời vụ, xu hướng thị trường, dữ liệu tiếp thị, TIPTOP GP cung cấp một loạt các mô hình dự đoán: dựa theo dữ liệu lịch sử nhân cho tỉ lệ phần trăm, số liệu bình quân động, số liệu bình quân gia quyền động, phương pháp cấp số nhân.</p>\r\n<p>Đối với hoạt động của tập đoàn mà nói cần có dự toán tổng hợp từ dưới lên trên, dự toán điều chỉnh từ trên xuống dưới và tiến hành phân tích nhiều góc độ: dự toán số lượng, mục tiêu, số lượng thực tế và số lượng lịch sử.</p>\r\n<hr class=\"hr\" />\r\n<p>Quản lý doanh thu tập đoàn</p>\r\n<p><a class=\"examplelink\" title=\"Quản lý doanh thu tập đoàn\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop3_vn.jpg\" alt=\"Quản lý doanh thu tập đoàn\" width=\"220\" height=\"178\" align=\"right\" /></a>Làm thế nào để kiểm soát và quản lý cơ cấu phân nhánh, tổng hợp dữ liệu của văn phòng chi nhánh và cửa hàng bán lẻ đã trở thành 1 thách thức không thể không đối mặt trong quá trình tập đoàn hóa doanh nghiệp.</p>\r\n<p>Quản lý doanh thu tập đoàn TIPTOP GP</p>\r\n<ul>\r\n<li>\r\n<p>Hỗ trợ cơ cấu tổ chức đa cấp như: trụ sở, khu vực lớn, khu vực nhỏ, tỉnh, chi nhánh, thành phố cấp quận.</p>\r\n</li>\r\n<li>\r\n<p>Hỗ trợ sản phẩn đa thuộc tính bao gồm: chủng loại, nhãn hiệu, series, hình dạng, kích cỡ, thuộc tính.</p>\r\n</li>\r\n<li>\r\n<p>Hỗ trợ quản lý đề xuất bán hàng, tập đoàn phân bổ việc bán hàng, quản lý hoàn trả, dòng sản phẩm.</p>\r\n</li>\r\n<li>\r\n<p>Quản lý nợ, kiểm soát bảo hành, kiểm soát tốc độ bán sản phẩm, kiểm soát lô sản phẩm và quản lý mã vạch, hộp mã vạch, trọng lượng, khối lượng .v.v…</p>\r\n</li>\r\n</ul>\r\n<hr class=\"hr\" />\r\n<p><a class=\"examplelink\" title=\"Quản lý sản xuất của tập đoàn\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop4_vn.jpg\" alt=\"Quản lý sản xuất của tập đoàn\" width=\"230\" height=\"296\" align=\"right\" /></a>Quản lý sản xuất của tập đoàn</p>\r\n<p>TIPTOP GP phù hợp với mô hình và nhu cầu sản xuất của nhiều ngành nghề, bao gồm sản xuất lặp đi lặp lại, sản xuất liên tục, sản xuất rời rạc và còn hỗ trợ bố cục tập đoàn hóa, tập hợp nhiều cứ điểm sản xuất, quản lý tập đoàn hóa không chỉ kiểm soát về mặt tài vụ. TIPTOP GP có đặc tính quản lý phù hợp với tính năng sản xuất, chẳng hạn như đa công xưởng, phân bổ công suất, quản lý sản xuất, quản lý công đoạn sản xuất, quản lý dự án, quản lý bảo trì RMA.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<hr class=\"hr\" />\r\n<p>Sắp xếp cải tiến doanh nghiệp</p>\r\n<p><a class=\"examplelink\" title=\"Sắp xếp cải tiến doanh nghiệp\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop5_vn.jpg\" alt=\"Sắp xếp cải tiến doanh nghiệp\" width=\"220\" height=\"171\" align=\"right\" /></a>Về mặt sắp xếp chi tiết công xưởng cùng với lập kế hoạch công suất và nguyên vật liệu, doanh nghiệp thường do không nắm bắt được tình trạng sản xuất thực tế của công xưởng và tiến độ thu mua nguyên vật liệu mà chỉ lập kế hoạch sản xuất dựa trên ước tính công suất và chính sách nhận đơn hàng riêng lẻ, nhưng vì cần nâng cao tiêu chuẩn phục vụ khách hàng và cam kết thời hạn giao hàng mà công xưởng thường phải tăng ca hoặc gia công bên ngoài để có thể giao hàng đúng hạn. Do hạn chế của việc qui hoạch nguyên vật liệu nên không thể xem xét công suất, lại vừa gây ra kế hoạch thu mua nguyên vật liệu riêng lẻ không thể phối hợp kế hoạch sản xuất, do vậy ảnh hưởng đến tiến độ sản xuất, dẫn đến vòng luẩn quẩn không thể đáp ứng thời gian giao hàng hoặc giá thành quá cao.</p>\r\n<p>Hệ thống sắp xếp và lập kế hoạch tân tiến (Advanced Planning and Scheduling: APS) sử dụng các mô hình tiên tiến và thuật toán hiện nay cung cấp kế hoạch sản xuất và qui hoạch nhu cầu nguyên vật liệu khả thi phù hợp với hạn chế nguồn lực của doanh nghiệp, cung cấp phân tích What-If, cho phép nhà hoạch địch nhanh chóng kết hợp các điều kiện hạn chế sản xuất và các thông tin liên quan của đơn đặt hàng, lưu trình chế tạo, tồn hàng, BOM, hạn chế công suất để lên kế hoạch và ra quyết định nhằm cân bằng lợi ích của doanh nghiệp với nhu cầu của khách hàng, thỏa mãn nhu cầu khách hàng và đối mặt với sự cạnh tranh khốc liệt trên thị trường.</p>\r\n<hr class=\"hr\" />\r\n<p><a class=\"examplelink\" title=\"Quản lý chuỗi cung ứng- phân phối\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop6_vn.jpg\" alt=\"Quản lý chuỗi cung ứng- phân phối\" width=\"220\" height=\"299\" align=\"right\" /></a>Quản lý chuỗi cung ứng- phân phối</p>\r\n<p>Trong kết cấu chuỗi phân phối trung tâm , TIPTOP GP cung cấp các kế hoạch phân phối hàng hóa. Dựa vào các đơn hàng của trụ sở chính và khu vực để điều phối kế hoạch phân phồi hàng hóa, tiến hành giao hàng cho khách hàng, và các công tác vận chuyển  hàng từ  trụ sở chính đến chi nhánh, hoặc  việc điều động hàng từ chi nhánh này đến chi nhánh khác.</p>\r\n<p>Tại trung tâm xử lý đơn đặt hàng và quản lý phân phối đa cấp, từng chi nhánh và công ty mẹ đều phải đối chiếu với đơn vị hạch toán của công ty mẹ. Do đó, dựa vào mô hình phân cấp phân phối và phân cấp  hạch toán, TIP TOP GP hổ trợ phương thức phân phối đa cấp.</p>\r\n<p>&nbsp;</p>\r\n<hr class=\"hr\" />\r\n<p>QUẢN LÝ PHÂN PHỐI BÁN LẺ<a class=\"examplelink\" title=\"QUẢN LÝ PHÂN PHỐI BÁN LẺ\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop7_vn.jpg\" alt=\"QUẢN LÝ PHÂN PHỐI BÁN LẺ\" width=\"220\" height=\"200\" align=\"right\" /></a></p>\r\n<p>Hỗ trợ quản lý chuỗi siêu thị, chợ, cửa hàng bách hóa, cửa hàng tiện lợi, cung cấp nhiều mô hình tổ chức như: mô hình quản lý đa cấp Trụ sở chính – Khu vực (hoặc trung tâm điều phối) – Cửa hàng; cung cấp nhiều mô hình bán hàng như: bán lẻ, đại lý giá gốc, đại lý có chiết khấu, liên kết; việc quản lý các hợp đồng cũng góp phần xử lý các vấn đề chi phí liên quan.</p>\r\n<p>Khâu thu mua được hỗ trợ rất nhiều phương pháp tính giá:</p>\r\n<ul>\r\n<li>\r\n<p>Cung cấp cơ chế và mô hình bù hàng linh hoạt, chủ động</p>\r\n</li>\r\n<li>\r\n<p>Cung cấp cách thức quản lý nhanh và kịp thời, có thể theo dõi toàn bộ quá trình lưu chuyển của mỗi sản phẩm, và ngược lại cũng có thể biết được nguồn mua hàng;</p>\r\n</li>\r\n<li>\r\n<p>Hỗ trợ nhiều phương thức bán háng: bán lẻ POS, bán hàng theo đơn đặt hàng, bán sỉ…</p>\r\n</li>\r\n<li>\r\n<p>Hỗ trợ nhiều phương thức chi trả: hệ thông POS có thể thanh toán tiền mặt, chi phiếu, thẻ tín dụng, thẻ mua hàng…</p>\r\n</li>\r\n<li>\r\n<p>Cung cấp nhiều phương thức khuyến mãi như:giá mở cửa, chiết khấu, phiếu giảm giá, kết hợp quà tặng…</p>\r\n</li>\r\n</ul>\r\n<hr class=\"hr\" />\r\n<p>QUẢN LÝ THU MUA</p>\r\n<p><a class=\"examplelink\" title=\"QUẢN LÝ THU MUA\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop8_vn.jpg\" alt=\"QUẢN LÝ THU MUA\" width=\"220\" height=\"256\" align=\"right\" /></a>Tiêu chuẩn hóa giao diện hệ thống, khả năng tích hợp hệ thống cao.</p>\r\n<ul>\r\n<li>\r\n<p>Cung cấp mô hình quản lý đa cấp \"Trụ sở chính + Chi nhánh khu vực + trung tâm thu mua.</p>\r\n</li>\r\n<li>\r\n<p>Hỗ trợ nhóm thu mua thực hiện tập trung hóa, lưu trình hóa và tiêu chuẩn hóa quản lý.</p>\r\n</li>\r\n</ul>\r\n<p>HOÀN CHỈNH KẾ HOẠCH QUẢN LÝ CHO THUÊ MẶT BẰNG</p>\r\n<ul>\r\n<li>\r\n<p>Thiết lập, phân chia diện tích và cung cấp sơ đồ mặt bằng của các tầng lầu, gian hàng, sân bãi...</p>\r\n</li>\r\n<li>\r\n<p>Dựa vào sơ đồ mặt bằng có thể biết được vị trí và tình hình thuê mướn của gian hàng, đồng thời dựa vào nhu cầu quản lý có thể tô màu thông tin để nắm được tình hình kinh doanh của doanh nghiệp.</p>\r\n</li>\r\n</ul>\r\n<p>QUẢN LÝ VÀ KIỂM SOÁT QUÁ TRÌNH ĐẦU TƯ</p>\r\n<p>Cung cấp các bước đầu tư (Nhà đầu tư đăng ký--&gt; nhà đầu tư tiềm năng--&gt; chính thức đầu tư) đồng thời ghi nhận quá trình đàm phán và các dữ liêu liên quan .</p>\r\n<p>THIẾT LẬP HỢP ĐỒNG ĐẦU TƯ CHẶT CHẼ VÀ LINH HoẠT</p>\r\n<ul>\r\n<li>\r\n<p>Phương pháp tính tiền thuê nhà linh hoạt, bao gồm: Tiền thuê cố định, giá thuê mức sàn, mua bảo hiểm cơ bản + giá thuê mức sàn…và nhiều cách kết hợp giá khác.</p>\r\n</li>\r\n<li>\r\n<p>Dựa vào điều kiện hợp đồng yêu cầu thiết lập các nội dung chiết khấu và phương thức thu tiền (tiền điện, phí vệ sinh, phí quản lý…)</p>\r\n</li>\r\n</ul>\r\n<p>QUẢN LÝ CHI TIẾT THÔNG TIN THÀNH VIÊN</p>\r\n<ul>\r\n<li>\r\n<p>Ngoài dữ liệu cơ bản ra, còn cung cấp dữ liệu chi tiết tiêu dùng, để sau này dễ phân tích kinh doanh và tăng cường quản lý quan hệ khách hàng.</p>\r\n</li>\r\n<li>\r\n<p>Cung cấp quy tắc tích lũy điểm của thành viên, đồng thời ghi nhận cụ thể lịch sử thay đổi chi phí/giá trị tích lũy của các thành viên.</p>\r\n</li>\r\n</ul>\r\n<p>ĐA DẠNG HÓA HÌNH THỨC TIẾP THỊ</p>\r\n<ul>\r\n<li>\r\n<p>Nhiều loại hình tiếp thị (tiếp thị thông thường, tổ hợp tiếp thị, tiếp thị diện rộng), nhiều hình thức khuyến mãi (giá đặc biệt, chiết khấu, giảm giá), đổi quà tặng.</p>\r\n</li>\r\n<li>\r\n<p>Có thể thiết lập nhiều địa điểm bán hàng với nhiều hình thức tiếp thị khác nhau. Ngoài ra có thể dựa vào đặc tính của sản phẩm mà thiết lập phạm vi tiếp thị.</p>\r\n</li>\r\n<li>\r\n<p>Cung cấp những phương thức thiết lập khoảng thời gian tiếp thị linh hoạt, bao gồm thời gian tiếp thị cố định và tiếp thị nhiều đợt.</p>\r\n</li>\r\n</ul>\r\n<p>HỖ TRỢ NHIỀU HÌNH THỨC THU NGÂN</p>\r\n<p>Cung cấp hệ thống thu tiền POS, máy thu tiền tự động với phương thức thu tiền linh hoạt và hiệu quả cao.</p>\r\n<p>TỰ ĐỘNG KẾT TOÁN, ĐỐI CHIẾU HỢP ĐỒNG NHANH CHÓNG</p>\r\n<p>Tự động hóa kết toán chi phí và quản lý đối chiếu sổ sách, đồng thời cung cấp chi tiết thông tin thu chi để giảm bớt công việc đối chiếu sổ sách của kế toán.</p>\r\n<p>CHÚ TRỌNG PHÂN TÍCH BÁO BIỂU VÀ DỮ LIỆU</p>\r\n<ul>\r\n<li>\r\n<p>Cung cấp các báo biểu mang tính trực quan, sơ đồ hóa, hổ trợ người quản lý nắm bắt kịp thời thông tin phân tích kinh doanh.</p>\r\n</li>\r\n<li>\r\n<p>Bao gồm các báo biểu phân tích thông thường như: tình hình kinh doanh, so sánh cùng kỳ, so sánh và phân tích tình hình phát triển kinh doanh cùng kỳ, phân tích hiệu quả kinh doanh của cửa hàng, mức độ đóng góp của doanh nghiệp, xếp hạng doanh thu các doanh nghiệp cùng ngành, phân tích bán hàng, phân tích tiêu dùng,…. 。</p>\r\n</li>\r\n</ul>\r\n<hr class=\"hr\" />\r\n<p>CHUỖI CUNG ỨNG VÀ THƯƠNG MẠI ĐIỆN TỬ</p>\r\n<p><a class=\"examplelink\" title=\"CHUỖI CUNG ỨNG VÀ THƯƠNG MẠI ĐIỆN TỬ\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop9_vn.jpg\" alt=\"CHUỖI CUNG ỨNG VÀ THƯƠNG MẠI ĐIỆN TỬ\" width=\"220\" height=\"182\" align=\"right\" /></a>Trong tương lai sự cạnh tranh giữa các doanh nghiệp không còn là sự cạnh của doanh nghiệp này với doanh nghiệp khác nữa mà là sự cạnh tranh giữa những hệ thống chuỗi cung ứng với nhau. Hệ thống TIPTOP GP EC (Thương mại điện tử) sẽ cung cấp những thông tin liên quan của các chuỗi cung ứng toàn cầu, tiến hành thay đổi và điều chỉnh một cách nhanh chóng, xây dựng chuỗi cung ứng hoàn chỉnh, đạt được sự hợp tác  quốc tế linh hoạt, nâng cao năng lực cạnh tranh của chuỗi giá trị ngành công nghiệp nói chung.</p>\r\n<p>NỘI DUNG QUẢN LÝ THU MUA ĐIỆN TỬ:</p>\r\n<ul>\r\n<li>\r\n<p>Xử lý công tác mua hàng thông qua trang web.</p>\r\n</li>\r\n<li>\r\n<p>Cung cấp chức năng so sánh giá trên mạng.</p>\r\n</li>\r\n<li>\r\n<p>Ghi nhận và tra tìm tình hình xuất kho của nhà cung cấp.</p>\r\n</li>\r\n<li>\r\n<p>Nhà cung cấp tự tra tình hình nhận hàng và thanh toán của doanh nghiệp.</p>\r\n</li>\r\n</ul>\r\n<p>NỘI DUNG QuẢN LÝ BÁN HÀNG:</p>\r\n<ul>\r\n<li>\r\n<p>Quản lý tồn kho bán hàng và cung cấp các báo biểu tra tìm liên quan.</p>\r\n</li>\r\n<li>\r\n<p>Quản lý giá bán ra.</p>\r\n</li>\r\n<li>\r\n<p>Quảng cáo thông tin khuyến mãi.</p>\r\n</li>\r\n<li>\r\n<p>Tập hợp thông tin đối thủ, thu thập và xử lý các vấn đề của khách hàng.</p>\r\n</li>\r\n</ul>\r\n<hr class=\"hr\" />\r\n<p><a class=\"examplelink\" title=\"QUẢN LÝ TÀI CHÍNH TẬP ĐOÀN\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop10_vn.jpg\" alt=\"QUẢN LÝ TÀI CHÍNH TẬP ĐOÀN\" width=\"350\" height=\"218\" align=\"right\" /></a>QUẢN LÝ TÀI CHÍNH TẬP ĐOÀN</p>\r\n<p>Đáp ứng giao dịch nội bộ, hỗ trợ công việc kế toán, hỗ trợ giải ngân các tài khoản các công ty con, đồng thời cung cấp sổ sách đối chiếu giữa các công ty và chức năng đối chiếu công nợ phải thu, phải trả giữa các các công ty.</p>\r\n<ul>\r\n<li>\r\n<p>Hỗ trợ hợp nhất quản lý theo cấp bậc và kết hợp với cách quản lý vượt ngoài quản lý cấp bậc;</p>\r\n</li>\r\n<li>\r\n<p>Hỗ trợ hợp nhất công tác bán hàng và tài chính kế toán;</p>\r\n</li>\r\n<li>\r\n<p>Đồng thời điều chỉnh bất thường và cung cấp các báo biểu tính toán của hệ thống kế toán;</p>\r\n</li>\r\n<li>\r\n<p>Tự động xóa nợ và đối chiếu sổ sách với các quyền hạn nội bộ khác nhau, tự động tính toán lợi nhuận của đơn vị, và tự động cấn trừ khấu hao tài sản cố định;</p>\r\n</li>\r\n<li>\r\n<p>Linh hoạt xác định phạm vi hợp nhất, dựa vào khu vực hoặc dựa vào báo cáo hợp nhất của các bộ phận từ các điễn đàn kinh tế.</p>\r\n</li>\r\n</ul>\r\n<hr class=\"hr\" />\r\n<p>QUẢN LÝ NGUỒN VỐN TẬP ĐOÀN</p>\r\n<p><a class=\"examplelink\" title=\"QUẢN LÝ NGUỒN VỐN TẬP ĐOÀN\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop11_vn.jpg\" alt=\"QUẢN LÝ NGUỒN VỐN TẬP ĐOÀN\" width=\"350\" height=\"233\" align=\"right\" /></a>Hỗ trợ và thực hiện quản lý tập trung, kiểm toán nguồn tài chính công ty và các quỹ ngân hàng, tối ưu hóa việc phân bổ vốn của Tập đoàn, đồng thời hỗ trợ việc phân bổ vốn nội bộ và vốn của các công ty con, để giúp chủ doanh nghiệp biết được những thất thoát nguồn vốn.</p>\r\n<ul>\r\n<li>\r\n<p>Hệ thống quản lý nguồn vốn của TIPTOP GP có thể mô phỏng rất nhiều mô hình, tự chọn mô hình công ty, mô hình bán hàng, thu mua...</p>\r\n</li>\r\n<li>\r\n<p>Đồng thời có thể đem quá trình cung ứng trước đó đưa vào thực hiện các công việc kế toán tiếp theo.</p>\r\n</li>\r\n<li>\r\n<p>Có thê tự chọn thời gian thực hiện</p>\r\n</li>\r\n<li>\r\n<p>Thao tác với nhiều loại tiền tệ (loại tiền giao dịch, kinh doanh tiền tệ, nhóm tiền tệ)</p>\r\n</li>\r\n<li>\r\n<p>Mô phỏng theo hoàn cảnh thực tế (nhập số tiền điều chỉnh để xem)</p>\r\n</li>\r\n</ul>\r\n<hr class=\"hr\" />\r\n<p>QUẢN LÝ NGÂN SÁCH TẬP ĐOÀN</p>\r\n<p><a class=\"examplelink\" title=\"QUẢN LÝ NGÂN SÁCH TẬP ĐOÀN\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop12_vn.jpg\" alt=\"QUẢN LÝ NGÂN SÁCH TẬP ĐOÀN\" width=\"350\" height=\"250\" align=\"right\" /></a>Nhóm quản lý ngân sách của TIPTOP GP hỗ trợ doanh nghiệp thực hiện lưu trình quản lý ngân sách một cách toàn diện.</p>\r\n<p>Cụ thể là: Thiết lập mục tiêu ngân sách, biên chế ngân sách, tổng hợp và kiểm toán, thực hiện ngân sách và hạch toán tài chính, phân tích và điều chỉnh ngân sách, đánh giá ngân sách và đánh giá tình hình kinh doanh.</p>\r\n<ul>\r\n<li>\r\n<p>TIPTOP GP dựa vào quá trình thiết lập ngân sách, cách thức quản lý và phân tích của doanh nghiệp để tiến hành quản lý, đảm bảo tính hiệu quả cho các mục tiêu chiến lược của công ty.</p>\r\n</li>\r\n<li>\r\n<p>Hỗ trợ thiết lập phân cấp quyền hạn tổ chức dự toán ngân sách, đồng thời tự thiết lập kế hoạch dự toán và chỉ định quyền hạn rõ ràng.</p>\r\n</li>\r\n<li>\r\n<p>Có thể lập mối tương quan giữa hệ thống dự toán ngân sách của công ty con và tập đoàn.</p>\r\n</li>\r\n<li>\r\n<p>Cho phép thiết lập đề án ngân sách; hỗ trợ tính toán tiền ngoại tệ; hỗ trợ dự toán ngân sách theo tháng, quý, năm.</p>\r\n</li>\r\n<li>\r\n<p>Hỗ trợ nhóm dự toán kết hợp với kiểm toán đa cấp, đồng thời hỗ trợ cơ chế Top-Down hoặc Bottom-Up <br />Có thể giới hạn theo trách nhiệm để xem số dư ngân sách dự toán và tiến độ quản lý ngân sách.</p>\r\n</li>\r\n<li>\r\n<p>Có thể thiết lập công cụ phân tích dự toán ngân sách dưới nhiều góc độ, phân tích đa chiều quá trình thực hiện và tiến độ hoàn thành kế hoạch ngân sách;</p>\r\n</li>\r\n<li>\r\n<p>Hỗ trợ điều chỉnh ngân sách và các quy trình kiểm toán.</p>\r\n</li>\r\n</ul>\r\n<hr class=\"hr\" />\r\n<p>QUẢN LÝ HIỆU SUẤT TẬP ĐOÀN</p>\r\n<p>CHÍNH SÁCH HÀNH ĐỘNG, CHUỖI CUNG ỨNG TOÀN CẦU</p>\r\n<p>Bậc thầy quản lý Peter Drucker đã từng nói “Sức mạnh của chính sách quản lý, quyết định sự sinh tồn của doanh nghiệp”. Đối mặt với sự biến động không ngừng của các doanh nghiệp, các cấp quản lý CEO và CIO phải có chính sách khôn ngoan, và nắm được giá trị sâu sắc của thông tin. Chính sách kịp thời và hành động hiệu quả sẽ giành chiến thắng trong lĩnh vực cung ứng toàn cầu.</p>\r\n<p>TIPTOP GP, tập trung vào việc cung cấp các sản phẩm và dịch vụ lâu dài về giải pháp kinh doanh thông minh “kinh doanh thông minh, hiệu quả”  kết hợp các giải pháp như : Thẻ cân bằng điểm (The Balanced Scorecard – BSC), chỉ số đánh giá thực hiện công việc (KPI), kinh doanh thông minh (BI), hệ thống quản lý thông tin (EIS), hệ thống quản lý quan hệ khách hàng (CRM), hệ thống kiến thức (KMS), hệ thống quản lý học tập (e_learning) và  trung tâm thông tin doanh nghiệp (WarRoom)… hỗ trợ CEO và CIO xây dựng nên chính sách quản lý ứng dụng công nghệ thông tin kết hợp giữa “quản lý hiệu quả kinh doanh” và “kinh doanh thông minh”, góp phần nâng cao giá trị doanh nghiệp.</p>\r\n<table border=\"0\" width=\"700\" cellspacing=\"0\" cellpadding=\"1\" align=\"center\">\r\n<tbody>\r\n<tr>\r\n<td align=\"center\" width=\"358\">\r\n<p><a class=\"examplelink\" title=\"QUẢN LÝ HIỆU SUẤT TẬP ĐOÀN\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop16_vn.jpg\" alt=\"QUẢN LÝ HIỆU SUẤT TẬP ĐOÀN\" width=\"350\" height=\"222\" /></a></p>\r\n</td>\r\n<td align=\"center\" width=\"360\">\r\n<p><a class=\"examplelink\" title=\"QUẢN LÝ HIỆU SUẤT TẬP ĐOÀN\"><img title=\"點擊放大\" src=\"http://www.digiwin.com.vn/vn/images/tiptop15_vn.jpg\" alt=\"QUẢN LÝ HIỆU SUẤT TẬP ĐOÀN\" width=\"350\" height=\"222\" /></a></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td class=\"h_legend\" colspan=\"2\" align=\"center\">\r\n<p>▲QUẢN LÝ HIỆU SUẤT TẬP ĐOÀN</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Ứng dụng công nghệ Business Objects của công ty Digiwin đã thêm vào chức năng liên kết chia sẻ thông tin thông qua MSN, Mobile, đổi mới mobile hóa hệ thống kinh doanh thông minh BI, và kịp thời hiển thị chỉ số đánh giá thực hiện công việc (KPI), chính sách online và ứng dụng bách khoa toàn thư KM. Thông tin 4 chiều (tích hợp mới, tính năng mới, công nghệ mới, ứng dụng mới) giúp các CEO và CIO có thể cùng nhau làm việc và thực hiện các chính sách mọi lúc, mọi nơi, kết nối toàn cầu.</p>\r\n<p align=\"center\"><img src=\"http://www.digiwin.com.vn/tw/images/tiptop17.jpg\" width=\"650\" height=\"564\" /></p>\r\n<hr size=\"1\" />'),
(2942, 111, '_solution_service', '<div id=\"CONTENT\">\r\n<div id=\"RR\">\r\n<div id=\"TXT\">\r\n<p>TIM ( TIPTOP Implementation Methodology )</p>\r\n<p>TIPTOP GP có rất nhiều kinh nghiệm về các loại hình doanh nghiệp, từ kinh nghiệm thực tế phát triển thành các phương pháp nhập liệu tiêu chuẩn, giảm thiểu bất cập và giảm số nhân công.</p>\r\n<table border=\"0\" width=\"95%\" cellspacing=\"0\" cellpadding=\"3\" align=\"center\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"middle\"><hr class=\"hr\" /></td>\r\n<td valign=\"middle\"><hr class=\"hr\" /></td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"341\">\r\n<p class=\"textG\"><span class=\"txt13\">Coi trọng trình tự hiệu quả đào tạo</span><br />Quá trình đào tạo tuân theo một trình tiêu chuẩn, thời gian đào tạo và mỗi giai đoạn sau khi đi vào sử dụng chính thức, dựa vào tình hình của mỗi khách hàng mà đưa ra những dịch vụ khác nhau; và ở mỗi giai đoạn đều được cố vấn ghi chú dữ liệu đầy đủ, đạt chuẩn thì mới được tiến hành giai đoạn kế tiếp.。</p>\r\n</td>\r\n<td valign=\"top\" width=\"341\">\r\n<p><span class=\"txt13\">Chuyển giao công nghệ không hạn chế</span><br />Cung cấp mã nguồn (source code), hoàn thành chuyển giao công nghệ, để khách hàng có thể \"tự chủ thông tin \"</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\"><hr class=\"hr\" /></td>\r\n<td valign=\"middle\"><hr class=\"hr\" /></td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\">\r\n<p class=\"textG\"><strong class=\"txt13\">Hỗ trợ doanh nghiệp thiết lập S.O.P riêng</strong><br />Dựa vào lưu trình riêng của mỗi doanh nghiệp và dựa vào nhu cầu  phát sinh  khi xem xét  tình hình  kinh doanh, thu mua, mô hình sản xuất , kết hợp giữa tình hình hiện tại và chính sách kinh doanh quản lý trong tương lai của doanh nghiệp để cùng nhau những điều chỉnh cơ bản.</p>\r\n</td>\r\n<td valign=\"top\">\r\n<p><span class=\"txt13\">Dịch vụ cố vấn độc quyền</span><br />Trong thời  gian huấn luyện, khách hàng có thể yêu cầu cố vấn theo sát, hỗ trợ và thảo luận chung.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\"><hr class=\"hr\" /></td>\r\n<td valign=\"middle\"><hr class=\"hr\" /></td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\">\r\n<p class=\"textG\"><span class=\"txt13\">Trung tâm dịch vụ TIPTOP </span><br />Sau khi đưa vào sử dụng chính thức, các vấn đề khách hàng gặp phải sẽ do bộ phận TSC hỗ trợ xử lý ; thông qua hệ thống điện thoại cung cấp cho khách hàng những mã  số và người phục vụ TSC.</p>\r\n</td>\r\n<td valign=\"top\">\r\n<p><strong><img src=\"http://www.digiwin.com.vn/tw/images/tiptop18.jpg\" width=\"100\" height=\"118\" align=\"right\" /></strong><span class=\"txt13\">Tiêu chuẩn thành công của việc đưa hệ thống vào sử</span><br />Thông qua TIPTOP GP kết toán giá thành và báo cáo kết quả chính xác trong 3 tháng , bắt đầu sử dụng chính thức hệ thống và chuyển sang giai đoạn TSC</p>\r\n<p>( TIPTOP Service Center )。</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\"><hr class=\"hr\" /></td>\r\n<td valign=\"middle\"><hr class=\"hr\" /></td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\">\r\n<p class=\"textG\"><span class=\"txt13\">CRM kho dữ liệu về các vấn đề khách hàng thường gặp</span><br />Dùng để ghi nhận quá trình tiếp nhận và xử lý vấn đề khách hàng, để theo dõi các vấn đề của hệ thống và dữ liệu chỉnh sửa các chức năng hệ thống, nâng cao giá trị của kho dữ liệu này.</p>\r\n</td>\r\n<td valign=\"top\">\r\n<p><strong><img src=\"http://www.digiwin.com.vn/tw/images/tiptop19.jpg\" width=\"100\" height=\"134\" align=\"right\" /></strong><span class=\"txt13\">Hệ thống học tập trực tuyến 24h</span><br />Trang web e-Service và e-Learning cung cấp dịch vụ 24h cho khách hàng của Digiwin. Ngoài thông tin “chương trình dạy học” ra còn có các thông tin liên quan như “tập hợp vấn đề khách hàng FAQ”,  “Call center tiến độ xử lý vấn đề” và “vấn đề khách hàng ủy thác”.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"middle\"><hr class=\"hr\" /></td>\r\n<td valign=\"middle\"><hr class=\"hr\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr size=\"1\" />\r\n<p align=\"right\"> </p>\r\n</div>\r\n</div>\r\n</div>\r\n<p>&nbsp;</p>\r\n<div id=\"dgwFooter\">\r\n<p class=\"link01\"> </p>\r\n<div class=\"link02\">\r\n<ul>\r\n<li>\r\n<p><img src=\"http://www.digiwin.com.vn/tw/images/digiwinSoft.png\" width=\"77\" height=\"18\" align=\"absmiddle\" />│<a href=\"http://www.digiwin.com.vn/\">Digiwin Software(Vietnam)</a>‧<a href=\"https://www.digiwin.com/tw/\" target=\"_blank\" rel=\"noopener\">Data Systems Consulting</a>‧<a href=\"http://www.digiwin.com\" target=\"_blank\" rel=\"noopener\">Digiwin Software</a></p>\r\n</li>\r\n</ul>\r\n</div>\r\n</div>'),
