INSERT INTO `dgw_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(2979, 368, '_industry_challenge', '<table border=\"0\" width=\"620\" cellspacing=\"1\" cellpadding=\"5\" align=\"center\" bgcolor=\"#b1b1b1\">\r\n<tbody>\r\n<tr>\r\n<td bgcolor=\"#CCCCCC\" width=\"47\"> </td>\r\n<td align=\"center\" valign=\"middle\" bgcolor=\"#CCCCCC\">\r\n<p>Thách thức ngành</p>\r\n</td>\r\n<td align=\"center\" valign=\"middle\" bgcolor=\"#CCCCCC\">\r\n<p>Trọng tâm quản lý</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td rowspan=\"9\" align=\"center\" bgcolor=\"#FFFFFF\">\r\n<p>Sản xuất</p>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"215\">\r\n<p>Góc chết quản lý đối với công cụ dụng cụ, đồ gá, đao cụ v.v.</p>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"354\">\r\n<p>Trong quá trình sản xuất cần phải có thông tin của những thiết bị hỗ trợ như công cụ dụng cụ, đồ gá, đao cụ v.v., nhu cầu lãnh dùng phát sinh thường xuyên, nhiều lúc cũng xảy ra tình trạng mượn ra, mượn vào, do đó việc quản lý không dễ dàng.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"215\">\r\n<p>Thiết kế sản xuất khuôn, và phân bổ khuôn khó quản lý</p>\r\n</td>\r\n<td valign=\"middle\" bgcolor=\"#FAF7F3\" width=\"354\">\r\n<p>Phân bổ chi phí khuôn, tuổi thọ khuôn, số lượng năng suất, và quản lý sửa chữa khuôn.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"215\">\r\n<p>Quản lý liệu dư (liệu thứ cấp)</p>\r\n</td>\r\n<td valign=\"middle\" bgcolor=\"#FFFFFF\" width=\"354\">\r\n<p>Liệu dư thứ cấp cần có sự quản lý, cần biết được có bao nhiêu vật liệu có khả năng thu hồi gia tăng trong mỗi lần sản xuất.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"215\">\r\n<p>Kế hoạch sản xuất cùng lúc thành phẩm và bán thành phẩm</p>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"354\">\r\n<p>Các thiết bị máy móc và khuôn công cụ cần thiết cho quá trình sản xuất rất đa dạng, chu kỳ sản xuất linh phụ kiện có thời gian dài ngắn bất nhất, công đoạn gia công phức tạp và việc khó xác định lưu trình dẫn đến việc quản lý sản phẩm dở dang không dễ, và thường phát sinh liệu biên khó giám sát.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"215\">\r\n<p>Trình tự gia công phức tạp</p>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"354\">\r\n<p>Tính không xác định của đơn đặt hàng, cùng với việc sản xuất linh phụ kiện cần phải có 1 chu kỳ nhất định, do đó việc cung ứng vật liệu không thích hợp sẽ dẫn đến tình trạng tích lũy tồn kho hoặc ngưng sản xuất đợi vật liệu, khó mà định ra kế hoạch sản xuất, thu mua với lượng và thời gian thích hợp.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"215\">\r\n<p>Sản phẩm dở dang khó quản lý</p>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"354\">\r\n<p>Thông thường áp dụng phương thức kết hợp tự sản xuất với ủy thác gia công, cần phải tiến hành quản lý theo dõi tiến độ sản xuất gia công, cũng như chất lượng và số lượng sản phẩm của các nhà gia công ủy thác.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">\r\n<p>Một sản phẩm nhiều mã, việc tạo mã trùng lặp</p>\r\n</td>\r\n<td valign=\"middle\" bgcolor=\"#FFFFFF\">\r\n<p>Tạo mã vật liệu chưa thể kiểm tra, dẫn đến việc tạo mã trùng lặp.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">\r\n<p>Biểu đồ kiểm soát ISO và TS16949 tốn nhiều thời gian và nhân lực</p>\r\n</td>\r\n<td valign=\"middle\" bgcolor=\"#FFFFFF\">\r\n<p>Sử dụng EXCEL làm biểu đồ quản lý chất lượng sản phẩm, khó quản lý và tốn nhiều thời gian cùng nhân lực.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"215\">\r\n<p>Phối hợp với doanh nghiệp hợp tác</p>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"354\">\r\n<p>Cung cấp nền tảng, để doanh nghiệp hợp tác có thể lên mạng lấy được các dữ liệu giao dịch liên quan.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td rowspan=\"2\" align=\"center\" bgcolor=\"#FFFFFF\">\r\n<p>Giá thành</p>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"215\">\r\n<p>Tính toán giá thành phức tạp</p>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"354\">\r\n<p>Hạng mục nguyên vật liệu linh phụ kiện nhiều và phức tạp, giá cả nguyên liệu biến động lớn, dẫn đến việc tính toán chính xác giá thành không dễ, không thể báo giá chuẩn xác nhanh chóng phản ánh ra thị trường.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"215\">\r\n<p>Biến động giá cả nguyên liệu nhanh chóng</p>\r\n</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"354\">\r\n<p>Do giá cả nguyên vật liệu luôn luôn biến động, chiếm 80% trong cấu trúc giá thành nguyên vật liệu, đồng thời do đặc tính chất liệu, hình dạng v.v., thường sẽ có tình trạng nhà cung ứng giao hàng nhiều hơn, do đó việc giám sát và quản lý thao tác xử lý nguyên vật liệu thực tế gặp nhiều khó khăn.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>'),
(2980, 368, '_industry_solution', '<p>(1)Đặc tính</p>\r\n<table border=\"0\" width=\"620\" cellspacing=\"1\" cellpadding=\"5\" align=\"center\" bgcolor=\"#b1b1b1\">\r\n<tbody>\r\n<tr>\r\n<td align=\"center\" valign=\"middle\" bgcolor=\"#CCCCCC\" width=\"146\">Đặc tính</td>\r\n<td align=\"center\" valign=\"middle\" bgcolor=\"#CCCCCC\" width=\"451\">Giải pháp</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"146\">Triển lãm tiếp thị</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">Thu thập danh thiếp và bảng câu hỏi hỗ trợ việc rút ngắn thời gian cho quy trình tiêu thụ của nhân viên nghiệp vụ, giành được cơ hội thương mại và kéo dãn khoảng cách cạnh tranh, phân tích hiệu ích đa chiều hỗ trợ nắm rõ tình hình hoạt động tiếp thị.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"146\">Quản lý phân bổ khuôn</td>\r\n<td valign=\"middle\" bgcolor=\"#FAF7F3\">Quản lý tuổi thọ khuôn, khi nào cần phải sửa chữa bảo trì, cũng như phân bổ chi phí khuôn của khách hàng và nhà cung ứng.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"146\">Tự động tạo mã</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">Chức năng nguyên tắc tạo mã dễ sử dụng và linh hoạt, có thể tự định nghĩa các mục liên quan, nhân viên tạo mã có thể nhanh chóng nhận biết mã vật liệu đó đã tạo mã hay chưa, nếu chưa tạo sẽ tự động hình thành tạo mã, người dùng có thể căn cứ vào sản phẩm, giải quyết vấn đề tạo mã phức tạp.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"146\">Thiết lập giao diện tích hợp cao giữa CAD với ERP</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\">Giữa các hệ thống có thể trao đổi dữ liệu với nhau, giảm thiểu việc nhập liệu lặp lại, rút ngắn thời gian nghiên cứu phát triển sản phẩm, hồ sơ sản phẩm thiết lập có thể đồng bộ biên tập thành file hình ảnh và cung cấp khả năng in ra. Bảng in CAD cũng có thể lấy được dữ liệu BOM và công đoạn sản xuất của ERP, tiện lợi cho nhân viên nghiên cứu phát triển sử dụng.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"146\">Sắp lịch và theo dõi công đoạn sản xuất</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">Có thể kết hợp căn cứ theo năng suất máy móc và năng suất khuôn/công cụ trực tiếp suy ra lịch trình sản xuất; nền tảng Web đa chức năng, dễ dàng nắm bắt mọi thông tin trong và ngoài xưởng. Cung cấp các loại bảng theo dõi điện tử đối với thiết bị sản xuất/lịch trình thực hiện. Thu thập dữ liệu chất lượng sản phẩm tự định, hỗ trợ theo dõi nắm bắt sản phẩm.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"146\">Chức năng tự động tính toán giá thành thực tế lớn mạnh</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\">Giá thành sản xuất của mỗi lệnh sản xuất và giá thành đơn vị của mỗi cấp bán thành phẩm cũng như thành phẩm cuối cùng, cho phép lựa chọn linh hoạt phân bổ theo chi phí và nhân công, cung cấp xác thực giá thành thực tế làm cơ sở báo giá, đồng thời kiểm tra sự chênh lệch giữa giá thành thực tế và giá thành tiêu chuẩn, từ đó cải thiện và hạ thấp giá thành sản xuất gia tăng lợi nhuận.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"146\">Quản lý nguồn sản phẩm</td>\r\n<td valign=\"middle\" bgcolor=\"#FFFFFF\">Nhanh chóng tra tìm bán thành phẩm hoặc thành phẩm có lỗi, nhanh chóng phản hồi vấn đề khách hàng phản ánh.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\" width=\"146\" height=\"120\">Quản lý chất lượng sản phẩm</td>\r\n<td valign=\"top\" bgcolor=\"#FAF7F3\">Đánh giá năng lực giám sát giá trị lượng hóa của chỉnh thể công đoạn sản xuất; những điểm bất thường trên biểu đồ quản lý, có thể ghi chú và hiển thị nguyên nhân bất thường cũng như có phương án điều chỉnh, thống kê những hạng mục không đạt nào có tần suất phát sinh cao nhất, sau đó tiến hành điều chỉnh đối với từng hạng mục này, nâng cao hiệu suất chỉnh thể.</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\" width=\"146\">Chuyển vào kế hoạch sản xuất hàng loạt</td>\r\n<td valign=\"top\" bgcolor=\"#FFFFFF\">Đưa vào kế hoạch lịch trình sản xuất, bao gồm tất cả nguyên vật liệu thu mua và bán thành phẩm sản xuất, và cả vật liệu gia công ủy thác, nhanh chóng phát sinh lệnh sản xuất và đơn đặt mua nhằm tiết kiệm nhân lực, đồng thời nâng cao tính chính xác và hiệu suất cho kế hoạch, giảm thời thời gian đợi vật liệu, hạ thấp giá thành tồn kho.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>(2)Ứng dụng gia tăng giá trị</p>\r\n<p>Hệ thống quản lý quan hệ khách hàng CRM</p>\r\n<p>Với mô hình quản lý lưu trình liên quan, từ lúc tham dự triển lãm có được dữ liệu của khách hàng, tiến đến giai đoạn báo giá gửi hàng mẫu, cho đến khi nhận được đơn đặt hàng chính thức của khách hàng. Và cũng ngay tại giai đoạn này thử thách năng lực tổng hợp và hiệu suất truyền đạt thông tin của đa số doanh nghiệp!</p>\r\n<p>Tích hợp đồng bộ PDM</p>\r\n<p>Rút ngắn thời gian phát triển sản phẩm mới, vận dụng hợp tác thiết kế và phát triển sản phẩm chung với khách hàng, giảm thiểu tỷ lệ chỉnh sửa, phản ứng nhanh chóng với nhu cầu thị trường, giảm thiểu giá thành quản lý cũng như hao hụt, giành được thị phần trước tiên.</p>\r\n<p>Hệ thống sắp xếp lịch trình sản xuất APS</p>\r\n<p>Giảm thiểu thời gian quy hoạch, hạ thấp gánh nặng nhân lực, một khi công ty mở rộng mô hình kinh doanh, thực hiện việc quy hoạch năng suất/vật liệu một cách có hiệu quả, nâng cao năng lực và hiệu suất ứng biến khi xử lý tình hình bất thường; hạ thấp tồn kho, nâng cao tỷ lệ chu chuyển tồn kho, đạt đến tính sản xuất kịp thời (JIT), nhanh chóng trả lời kỳ giao cho khách hàng, nâng cao tỷ lệ đạt giao đơn hàng, làm cơ sở điều phối giữa sản xuất và tiêu thụ.</p>\r\n<p>Thương vụ trực tuyến, cơ hội kinh doanh vô hạn e-B Online</p>\r\n<p>Bên mua：</p>\r\n<p>1.Đẩy nhanh việc truyền đạt thông tin với các nhà cung ứng trong chuỗi cung ứng, nâng cao năng lực sản xuất.</p>\r\n<p>2.Rút ngắn chu kỳ chuỗi cung ứng, nâng cao năng lực cạnh tranh tổng thể.</p>\r\n<p>3.Nâng cao tính chính xác kỳ giao</p>\r\n<p>4.Đẩy nhanh thời gian phản hồi đơn đặt hàng khách hàng</p>\r\n<p>Bên bán：  </p>\r\n<p>1.Nâng cao hiệu suất phản hồi đơn đặt hàng khách hàng</p>\r\n<p>2.Tăng cường năng lực thao tác điện tử hóa</p>\r\n<p>3.Liên kết chặt chẽ với thông tin khách hàng, nâng cao mức tín nhiệm khách hàng</p>\r\n<h3><a href=\"http://www.digiwin.com.vn/vn/solution_SFT1.html\">Theo dõi tiến độ sản xuất trong xưởng SFT</a></h3>\r\n<p>SFT có thể được định nghĩa đơn giản là “Hệ thống theo dõi thông tin sản xuất tức thời” cho doanh nghiệp, cung cấp cho doanh nghiệp khả năng nắm bắt thông tin cả lưu trình sản xuất trọn vẹn từ lúc nhận đơn, cung cấp vật liệu, sản xuất, ủy thác giao ngoài, cho đến hoàn công nhập kho, liên kết chặt chẽ với công đoạn sản xuất tại hiện trường và thao tác ERP, thực hiện quản lý vòng tuần hoàn doanh nghiệp．</p>\r\n<p>Theo dõi nguồn sản phẩm TRC</p>\r\n<p>1.Tra tìm nhanh chóng bán thành phẩm hoặc thành phẩm có thể có lỗi.</p>\r\n<p>2.Phản hồi nhanh chóng vấn đề khách hàng phản ánh, hạn chế vấn đề phát sinh lặp lại trong tương lai</p>\r\n<p>3.Thiết lập niềm tin khách hàng và tính cạnh tranh thương hiệu</p>\r\n<p>4.Dự phòng vấn đề phát sinh và giảm thiểu nguy cơ bồi thường</p>\r\n<p>5. “Có năng lực hồi tố” sẽ là điều kiện cơ bản tiếp nhận đơn của doanh nghiệp</p>\r\n<p>Giám sát chất lượng sản phẩm SPC</p>\r\n<p>Trong tình hình cạnh tranh khốc liệt như ngày nay, SPC (Statistical Process Control) là 1 công cụ duy trì năng lực sản xuất và tính cạnh tranh cho doanh nghiệp, đồng thời còn là 1 trong những thủ pháp quan trọng trong quản lý sản phẩm. Phương thức truyền thống là tăng cường kiểm nghiệm để đảm bảo chất lượng sản phẩm, thường chỉ có thể xử lý tính tiêu cực và báo phế sản phẩm, mà không thể đạt được mục tiêu dự phòng cho công đoạn sản xuất. Và mục đích của SPC, với phương pháp phân tích thống kê tình hình chất lượng sản phẩm của dây chuyền sản xuất, có thể phát hiện kịp thời và loại bỏ nhân tố không ổn định của công đoạn sản xuất, đạt đến mục tiêu ổn định chất lượng sản phẩm, hạ thấp tỷ lệ không đạt.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
